public class Main {
    static int parseCount(String text) {
        try {
            return Integer.parseInt(text);
        } catch (NumberFormatException error) {
            return -1;
        }
    }

    public static void main(String[] args) {
        System.out.println(parseCount("12"));
        System.out.println(parseCount("twelve"));
    }
}
